void sheet_load_tiles(uint8_t first, uint8_t count, uint8_t dest) BANKED
{
    set_bkg_data(dest, count, &sheet_tiles_data[(uint16_t)first * 16]);
}

void sheet_load_metatile(uint8_t cell, uint8_t dest) BANKED
{
    const uint8_t *mt = &sheet_metatile_tiles[(uint16_t)cell * 4];
    uint8_t i;
    for (i = 0; i < 4; i++) {
        set_bkg_data((uint8_t)(dest + i), 1, &sheet_tiles_data[(uint16_t)mt[i] * 16]);
    }
}

